<?php require_once __DIR__.'/../../includes/functions.php';admin_required();$posterId=(int)($_GET['id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(isset($_POST['hotspot_poster_id'])){$posterId=(int)$_POST['hotspot_poster_id'];$s=db()->prepare('INSERT INTO ar_hotspots(poster_id,attraction_id,label,x,y,width,height,z_index,video_url,content_type) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$posterId,$_POST['attraction_id']?:null,trim((string)$_POST['label']),max(0,min(1,(float)$_POST['x'])),max(0,min(1,(float)$_POST['y'])),.2,.12,1,trim((string)($_POST['video_url']??''))?:null,$_POST['content_type']??'card']);flash('success','Hotspot added.');redirect('index.php?id='.$posterId);} $name=trim((string)$_POST['name']);$file=upload_image($_FILES['poster_image']??[],'posters');$target=$_FILES['target_file']??[];$targetFile=null;if(($target['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){if(($target['error']??1)!==UPLOAD_ERR_OK||strtolower(pathinfo($target['name']??'',PATHINFO_EXTENSION))!=='mind')throw new RuntimeException('Target file must be a valid .mind file.');$targetFile='assets/ar-targets/'.bin2hex(random_bytes(12)).'.mind';$targetPath=TARGET_DIR.basename($targetFile);if(!is_dir(TARGET_DIR))mkdir(TARGET_DIR,0755,true);if(!move_uploaded_file($target['tmp_name'],$targetPath))throw new RuntimeException('Could not save target file.');}$targetStatus=$targetFile?'READY':'NOT_COMPILED';if(!$name)throw new RuntimeException('Poster name is required.');if($posterId){$sql=$file||$targetFile?'UPDATE ar_posters SET name=?,description=?'.($file?',poster_image=?':'').($targetFile?',target_file=?,target_status="READY",target_compiled_at=NOW()':'').(!$targetFile&&$file?',target_status="NOT_COMPILED",target_file=NULL':'').' WHERE id=?':'UPDATE ar_posters SET name=?,description=? WHERE id=?';$values=[$name,$_POST['description']];if($file)$values[]=$file;if($targetFile)$values[]=$targetFile;$values[]=$posterId;$s=db()->prepare($sql);$s->execute($values);}else{if(!$file)throw new RuntimeException('Poster image is required.');$s=db()->prepare('INSERT INTO ar_posters(name,description,poster_image,target_file,target_status,target_compiled_at) VALUES(?,?,?, ?,?,'.($targetFile?'NOW()':'NULL').')');$s->execute([$name,$_POST['description'],$file,$targetFile,$targetStatus]);$posterId=(int)db()->lastInsertId();}flash('success','Poster saved.');redirect('index.php?id='.$posterId);}catch(Throwable $e){flash('danger',$e->getMessage());}}if(isset($_GET['delete'])){db()->prepare('DELETE FROM ar_posters WHERE id=?')->execute([(int)$_GET['delete']]);redirect('index.php');}$poster=$posterId?(function()use($posterId){$s=db()->prepare('SELECT * FROM ar_posters WHERE id=?');$s->execute([$posterId]);return $s->fetch();})():null;$posters=db()->query('SELECT * FROM ar_posters ORDER BY created_at DESC')->fetchAll();$attractions=db()->query("SELECT id,name FROM attractions WHERE status='active' ORDER BY name")->fetchAll();$hotspots=$posterId?(function()use($posterId){$s=db()->prepare('SELECT h.*,a.name attraction_name FROM ar_hotspots h LEFT JOIN attractions a ON a.id=h.attraction_id WHERE h.poster_id=? ORDER BY h.id');$s->execute([$posterId]);return $s->fetchAll();})():[];$title='AR Posters';include __DIR__.'/../../includes/header.php';?>
<main class="container py-5"><div class="d-flex justify-content-between"><h1 class="display-serif">AR Posters</h1><a href="?new=1" class="btn btn-success">Add poster</a></div><div class="alert alert-info mt-4"><strong>还没有 .mind 文件？</strong> 先准备一张清晰的海报图片，然后打开 <a href="https://hiukim.github.io/mind-ar-js-doc/tools/compile/" target="_blank" rel="noopener">MindAR 官方 Target Compiler</a> 生成并下载 .mind 文件，再在下面的表单上传。生成工具会在新标签页打开。如果该页面也无法访问，请使用项目本地的命令行编译器。</div><?php if(isset($_GET['new'])||$poster):?><div class="card p-4 my-4"><form method="post" enctype="multipart/form-data"><?=csrf_field()?><label class="form-label">Poster name<input name="name" class="form-control" required value="<?=e($poster['name']??'')?>"></label><label class="form-label">Description<textarea name="description" class="form-control"><?=e($poster['description']??'')?></textarea></label><label class="form-label">Poster image (JPG/PNG/WebP, max 8 MB)<input type="file" name="poster_image" class="form-control" accept="image/jpeg,image/png,image/webp" <?=!$poster?'required':''?>></label><label class="form-label mt-2">MindAR target (.mind)<input type="file" name="target_file" class="form-control" accept=".mind"></label><button class="btn btn-success mt-2">Save poster</button></form></div><?php endif;?><?php if($poster):?><div class="card p-4 mb-4"><div class="d-flex justify-content-between"><h2 class="h4">Hotspot editor: <?=e($poster['name'])?></h2><span class="badge text-bg-<?=$poster['target_status']==='READY'?'success':'warning'?>"><?=e($poster['target_status'])?></span></div><div class="poster-editor mt-3" id="posterEditor"><img id="posterImage" src="<?=e('../../'.$poster['poster_image'])?>" alt="<?=e($poster['name'])?>"><?php foreach($hotspots as $h):?><button class="hotspot" style="left:<?=$h['x']*100?>%;top:<?=$h['y']*100?>%;width:<?=$h['width']*100?>%;height:<?=$h['height']*100?>%" data-id="<?=$h['id']?>" title="Drag to reposition"><span><?=e($h['label'])?></span></button><?php endforeach;?></div><form id="hotspotForm" method="post" class="row g-2 mt-3"><?=csrf_field()?><input type="hidden" name="hotspot_poster_id" value="<?=$posterId?>"><div class="col-md-3"><input class="form-control" name="label" placeholder="Hotspot label" required></div><div class="col-md-3"><select class="form-select" name="attraction_id"><option value="">Select attraction</option><?php foreach($attractions as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><input class="form-control" name="video_url" placeholder="Video URL (optional)" type="url"></div><div class="col-md-2"><select class="form-select" name="content_type"><option value="card">Card</option><option value="video">Video</option><option value="link">Link</option></select></div><div class="col-md-2"><input class="form-control" name="x" placeholder="x 0-1" type="number" min="0" max="1" step=".001" required><input class="form-control mt-1" name="y" placeholder="y 0-1" type="number" min="0" max="1" step=".001" required></div><div class="col-md-1"><button class="btn btn-outline-success w-100">Add</button></div></form><p class="small text-muted mt-3 mb-0">Positions are normalized (0–1), so layouts remain responsive. Drag an existing hotspot to update its position through the JSON API below.</p></div><?php endif;?><div class="card p-3"><table class="table align-middle"><thead><tr><th>Poster</th><th>Target</th><th>Hotspots</th><th></th></tr></thead><tbody><?php foreach($posters as $p):?><tr><td><?=e($p['name'])?></td><td><span class="badge text-bg-<?=$p['target_status']==='READY'?'success':'secondary'?>"><?=e($p['target_status'])?></span></td><td><?= (int)db()->query('SELECT COUNT(*) FROM ar_hotspots WHERE poster_id='.(int)$p['id'])->fetchColumn()?></td><td class="text-end"><a href="?id=<?=$p['id']?>" class="btn btn-sm btn-outline-success">Edit / hotspots</a> <a data-confirm="Delete this poster and hotspots?" href="?delete=<?=$p['id']?>" class="btn btn-sm btn-outline-danger">Delete</a></td></tr><?php endforeach;?></tbody></table></div></main><script>document.querySelectorAll('.hotspot').forEach(function(el){let drag=false;el.addEventListener('pointerdown',()=>{drag=true;el.setPointerCapture(event.pointerId)});el.addEventListener('pointerup',()=>drag=false);el.addEventListener('pointermove',e=>{if(!drag)return;const r=document.getElementById('posterEditor').getBoundingClientRect();el.style.left=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width))*100+'%';el.style.top=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))*100+'%';});});</script><?php include __DIR__.'/../../includes/footer.php';?>
